namespace{class SongBrain final:public juce::Component{public:explicit SongBrain(MainComponent&o):owner(o){title.setText("AI SONG BRAIN",juce::dontSendNotification);title.setColour(juce::Label::textColourId,juce::Colour(0xff8edcff));title.setFont(juce::Font(13,juce::Font::bold));addAndMakeVisible(title);add(analyse,"ANALYSE IDEA",[this]{analyseIdea();});add(build,"SMART DEVELOP",[this]{smartDevelop();});add(transition,"TRANSITION",[this]{transitionIt();});add(breakdown,"BREAKDOWN",[this]{breakdownIt();});add(climax,"CLIMAX",[this]{climaxIt();});add(close,"CLOSE BRAIN",[this]{setVisible(false);});status.setColour(juce::Label::textColourId,juce::Colour(0xffb8c3cf));status.setFont(juce::Font(10));addAndMakeVisible(status);setOpaque(true);}void paint(juce::Graphics&g)override{g.fillAll(juce::Colour(0xff11161c));g.setColour(juce::Colour(0xff4b7690));g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(1),7,1.5f);}void resized()override{title.setBounds(12,8,getWidth()-120,22);close.setBounds(getWidth()-112,6,100,25);int gap=6,w=(getWidth()-24-gap)/2;analyse.setBounds(12,40,w,32);build.setBounds(12+w+gap,40,w,32);int w3=(getWidth()-24-gap*2)/3;transition.setBounds(12,80,w3,30);breakdown.setBounds(12+w3+gap,80,w3,30);climax.setBounds(12+2*(w3+gap),80,w3,30);status.setBounds(12,118,getWidth()-24,30);}private:template<class F>void add(juce::TextButton&b,const char*t,F f){b.setButtonText(t);b.setColour(juce::TextButton::buttonColourId,juce::Colour(0xff202832));b.setColour(juce::TextButton::textColourOffId,juce::Colours::white);b.onClick=f;addAndMakeVisible(b);}std::vector<MidiEngine::NoteEvent>notes()const{return owner.midiEngine.getNotesCopy();}void say(const juce::String&s){status.setText(s,juce::dontSendNotification);}bool create(std::vector<MidiEngine::NoteEvent>n,double start,const juce::String&m){if(n.empty())return false;owner.midiEngine.clear();for(auto&a:n)owner.midiEngine.addNote(a.startTick,a.lengthTicks,a.pitch,a.velocity,a.channel);owner.midiClipStartSeconds=start;owner.midiClipLengthUserDefined=false;owner.updateMidiClipTiming();bool ok=commitLibertyAIGeneratedClip(owner,true);say(ok?m:"Clip creation failed");return ok;}void analyseIdea(){auto n=notes();if(n.empty()){say("No active idea");return;}int lo=127,hi=0,v=0;for(auto&a:n){lo=juce::jmin(lo,(int)a.pitch);hi=juce::jmax(hi,(int)a.pitch);v+=a.velocity;}say("Range "+juce::String(lo)+"-"+juce::String(hi)+" | notes "+juce::String((int)n.size())+" | avg velocity "+juce::String(v/juce::jmax(1,(int)n.size())));}void smartDevelop(){auto s=notes();if(s.empty())return;double base=owner.midiClipStartSeconds,len=juce::jmax(.25,owner.midiClipLengthSeconds);for(int x=0;x<3;++x){auto o=s;for(size_t i=0;i<o.size();++i){o[i].velocity=(std::uint8_t)juce::jlimit(1,127,(int)o[i].velocity+5*(x+1));if(x&&o[i].channel!=10&&i%(5-x)==0)o[i].pitch=(std::uint8_t)juce::jlimit(0,127,(int)o[i].pitch+(x==1?7:12));}create(o,base+len*(x+1),"Smart development created");}say("Lift / Expansion / Climax created");}void transitionIt(){auto s=notes();if(s.empty())return;auto q=MidiEngine::ticksPerQuarterNote,end=owner.midiEngine.getLengthTicks();for(int i=0;i<8;++i){MidiEngine::NoteEvent n;n.startTick=juce::jmax<std::int64_t>(0,end-q)+i*q/8;n.lengthTicks=q/12;n.pitch=(std::uint8_t)juce::jlimit(0,127,(int)s.back().pitch+i);n.velocity=72+i*6;n.channel=s.back().channel;s.push_back(n);}create(s,owner.midiClipStartSeconds+owner.midiClipLengthSeconds,"Transition created");}void breakdownIt(){auto s=notes();std::vector<MidiEngine::NoteEvent>o;for(size_t i=0;i<s.size();++i)if(i%2==0){auto n=s[i];n.velocity=(std::uint8_t)juce::jmax(1,(int)n.velocity-20);if(n.channel!=10)n.pitch=(std::uint8_t)juce::jmax(0,(int)n.pitch-12);o.push_back(n);}create(o,owner.midiClipStartSeconds+owner.midiClipLengthSeconds,"Breakdown created");}void climaxIt(){auto s=notes();size_t c=s.size();for(auto&n:s)n.velocity=(std::uint8_t)juce::jlimit(1,127,(int)n.velocity+14);for(size_t i=0;i<c;++i)if(s[i].channel!=10&&i%4==0){auto n=s[i];n.pitch=(std::uint8_t)juce::jlimit(0,127,(int)n.pitch+12);s.push_back(n);}create(s,owner.midiClipStartSeconds+owner.midiClipLengthSeconds,"Climax created");}MainComponent&owner;juce::Label title,status;juce::TextButton analyse,build,transition,breakdown,climax,close;};
class Controller:private juce::Timer{public:explicit Controller(MainComponent&o):owner(o){launcher.setButtonText("AI SONG BRAIN");launcher.setColour(juce::TextButton::buttonColourId,juce::Colour(0xff31506a));launcher.setColour(juce::TextButton::textColourOffId,juce::Colours::white);launcher.onClick=[this]{if(brain){brain->setVisible(true);brain->toFront(false);}};startTimerHz(2);}~Controller(){shutdown();}void shutdown(){if(stopped.exchange(true))return;stopTimer();brain.reset();launcher.setVisible(false);}private:juce::Component*panel(){for(int i=0;i<owner.getNumChildComponents();++i){auto*c=owner.getChildComponent(i);if(!c)continue;for(int j=0;j<c->getNumChildComponents();++j)if(auto*l=dynamic_cast<juce::Label*>(c->getChildComponent(j)))if(l->getText()=="LIBERTY AI MUSIC")return c;}return nullptr;}void timerCallback()override{auto*p=panel();if(!p)return;if(parent!=p){parent=p;parent->addAndMakeVisible(launcher);brain=std::make_unique<SongBrain>(owner);parent->addChildComponent(*brain);brain->setVisible(false);}auto lb=juce::Rectangle<int>(20,270,juce::jmax(280,p->getWidth()-40),38);if(launcher.getBounds()!=lb)launcher.setBounds(lb);int h=156,y=juce::jlimit(318,juce::jmax(318,p->getHeight()-h-20),318);auto bb=juce::Rectangle<int>(20,y,juce::jmax(280,p->getWidth()-40),h);if(brain&&brain->getBounds()!=bb)brain->setBounds(bb);}MainComponent&owner;juce::Component*parent=nullptr;juce::TextButton launcher;std::unique_ptr<SongBrain>brain;std::atomic<bool>stopped{false};};std::map<MainComponent*,std::unique_ptr<Controller>>controllers;class Bootstrap:private juce::Timer{public:Bootstrap(){startTimerHz(4);}~Bootstrap(){shutdown();}void shutdown(){stopTimer();for(auto&i:controllers)if(i.second)i.second->shutdown();controllers.clear();}private:void timerCallback()override{auto&d=juce::Desktop::getInstance();for(int i=0;i<d.getNumComponents();++i)if(auto*w=dynamic_cast<juce::DocumentWindow*>(d.getComponent(i)))if(auto*m=dynamic_cast<MainComponent*>(w->getContentComponent()))if(!controllers.count(m))controllers.emplace(m,std::make_unique<Controller>(*m));}};Bootstrap bootstrap;}
void shutdownLibertyAISongIntelligenceController(){bootstrap.shutdown();}
